MBIM_CID_QMI_MSG = 1
QMI_CTL, QMI_UIM = 0x00, 0x0B
CTL_ALLOCATE_CID, CTL_RELEASE_CID = 0x0022, 0x0023
UIM_SEND_APDU, UIM_LOGICAL_CHANNEL = 0x003B, 0x003F
SLOT = 1
QMI_TIMEOUT = 15
DIAL_TIMEOUT = 60
UP_TIMEOUT = 20          # for the adapter and its addresses to appear
DHCP_TIMEOUT = 15
