class Error(Exception):
    pass


def log(msg: str):
    print(msg, file=sys.stderr, flush=True)


# -- WinRT, on a loop of its own ----------------------------------------------

class WinRT:
    """An asyncio loop in a thread, for WinRT's async operations; the rest
    of this script (and the SIM server's threads) is synchronous. Every WinRT
    call goes through this thread: an operation started on one thread and
    awaited on another may never complete."""

    def __init__(self):
        self.loop = asyncio.new_event_loop()
        threading.Thread(target=self.loop.run_forever, daemon=True).start()

    def call(self, fn):
        """fn() on the loop's thread."""
        async def run():
            return fn()
        return asyncio.run_coroutine_threadsafe(run(), self.loop).result(30)

    def run(self, start, timeout: float, what: str = "operation"):
        """Await the operation start() returns, started on the loop's
        thread."""
        async def run():
            return await bounded(start(), timeout, what)
        return asyncio.run_coroutine_threadsafe(
            run(), self.loop).result(timeout + 5)


async def bounded(op, timeout: float, what: str = "operation"):
    """await op with a timeout. Not asyncio.wait_for: it waits for the
    cancellation to finish, which a stuck WinRT operation never does."""
    fut = asyncio.ensure_future(op)
    done, _ = await asyncio.wait({fut}, timeout=timeout)
    if not done:
        fut.cancel()
        raise Error(f"{what}: no answer within {timeout:.0f}s")
    return fut.result()


def buffer(data: bytes):
    w = DataWriter()
    w.write_bytes(data)
    return w.detach_buffer()


def modem():
    m = MobileBroadbandModem.get_default()
    if m is None:
        raise Error("no mobile broadband modem")
    return m


# -- QMI over MBIM ------------------------------------------------------------

def tlv(t: int, v: bytes) -> bytes:
    return struct.pack("<BH", t, len(v)) + v


def parse_tlvs(b: bytes) -> dict[int, bytes]:
    out = {}
    while len(b) >= 3:
        t, n = struct.unpack_from("<BH", b)
        out[t] = b[3:3 + n]
        b = b[3 + n:]
    return out


class Qmi:
    """QMI services through the modem's QMI-over-MBIM device service: a
    QMUX message in each MBIM set command, its response in the reply."""

    def __init__(self, rt: WinRT):
        self.rt = rt
        self.lock = threading.Lock()
        self.session = None
        self.cids: dict[int, int] = {}
        self.tid = itertools.count(random.randint(1, 0x7000))

    def _open(self):
        # Keep the modem and service objects referenced while the session
        # is open. Reading SupportedCommands before OpenCommandSession is not
        # optional: without it, the session's first command often never
        # completes.
        self.modem = modem()
        self.service = self.modem.get_device_service(QMI_SERVICE)
        if self.service is None:
            raise Error("the modem has no QMI-over-MBIM device service")
        list(self.service.supported_commands)
        self.session = self.service.open_command_session()
        self.cids = {}

    def _send(self, svc: int, cid: int, sdu: bytes) -> bytes:
        frame = struct.pack("<BHBBB", 1, 5 + len(sdu), 0, svc, cid) + sdu
        r = self.rt.run(lambda: self.session.send_set_command_async(
            MBIM_CID_QMI_MSG, buffer(frame)), QMI_TIMEOUT, "QMI command")
        if r.status_code:
            raise Error(f"QMI over MBIM: MBIM status {r.status_code}")
        data = bytes(r.response_data)
        if len(data) < 6 or data[0] != 1 or data[4] != svc:
            raise Error(f"QMI over MBIM: unexpected reply {data[:16].hex()}")
        return data[6:]

    def _ctl(self, msg: int, body: bytes) -> dict[int, bytes]:
        tid = next(self.tid) & 0xFF or 1
        sdu = self._send(QMI_CTL, 0,
                         struct.pack("<BBHH", 0, tid, msg, len(body)) + body)
        return self._result(msg, parse_tlvs(sdu[6:]))

    def _cid(self, svc: int) -> int:
        if svc not in self.cids:
            t = self._ctl(CTL_ALLOCATE_CID, tlv(1, bytes([svc])))
            self.cids[svc] = t[1][1]
        return self.cids[svc]

    @staticmethod
    def _result(msg: int, t: dict[int, bytes]) -> dict[int, bytes]:
        if 2 not in t:
            raise Error(f"QMI 0x{msg:04x}: no result")
        status, err = struct.unpack("<HH", t[2][:4])
        if status:
            raise QmiError(msg, err)
        return t

    def request(self, svc: int, msg: int, body: bytes = b"") -> dict[int, bytes]:
        with self.lock:
            try:
                if self.session is None:
                    self.rt.call(self._open)
                cid = self._cid(svc)
                tid = next(self.tid) & 0xFFFF or 1
                sdu = self._send(svc, cid, struct.pack(
                    "<BHHH", 0, tid, msg, len(body)) + body)
            except QmiError:
                raise
            except (Error, OSError) as e:
                self.session = None  # modem gone or wedged: reopen next time
                raise Error(f"QMI over MBIM: {e}")
            return self._result(msg, parse_tlvs(sdu[7:]))

    def close(self):
        with self.lock:
            if self.session is None:
                return
            for svc, cid in self.cids.items():
                try:
                    self._ctl(CTL_RELEASE_CID, tlv(1, bytes([svc, cid])))
                except (Error, OSError):
                    pass
            self.cids = {}
            try:
                self.rt.call(self.session.close_session)
            except OSError:
                pass
            self.session = None


class QmiError(Error):
    def __init__(self, msg: int, code: int):
        super().__init__(f"QMI 0x{msg:04x}: error 0x{code:04x}")
        self.code = code


# -- SIM ----------------------------------------------------------------------

def channel_cla(cla: int, channel: int) -> int:
    """CLA for a logical channel (TS 102 221 10.1.1)."""
    if channel <= 3:
        return (cla & 0x80) | channel
    return (cla & 0x80) | 0x40 | (channel - 4)


class UimChannel:
    """What server.Usim calls a connection: APDUs over QMI UIM, on a logical
    channel opened when an application is selected."""

    def __init__(self, qmi: Qmi):
        self.qmi = qmi
        self.channel = None

    def open(self, aid: bytes):
        self.close()
        try:
            t = self.qmi.request(QMI_UIM, UIM_LOGICAL_CHANNEL,
                                 tlv(0x01, bytes([SLOT]))
                                 + tlv(0x10, bytes([len(aid)]) + aid))
        except QmiError as e:
            raise simserver.CardError(f"opening a channel to {aid.hex()}: {e}")
        sw = t.get(0x11, b"\x90\x00")
        if sw[0] not in (0x90, 0x91) or 0x10 not in t:
            raise simserver.CardError(f"opening a channel to {aid.hex()}: "
                                      f"SW={sw.hex().upper()}")
        self.channel = t[0x10][0]

    def transmit(self, apdu: list[int]):
        if self.channel is None:
            raise simserver.CardError("no application selected")
        apdu = bytes([channel_cla(apdu[0], self.channel)]) + bytes(apdu[1:])
        try:
            t = self.qmi.request(QMI_UIM, UIM_SEND_APDU,
                                 tlv(0x01, bytes([SLOT]))
                                 + tlv(0x02, struct.pack("<H", len(apdu)) + apdu)
                                 + tlv(0x10, bytes([self.channel])))
        except Error as e:
            raise simserver.CardError(str(e))
        resp = t.get(0x10, b"")
        resp = resp[2:2 + struct.unpack("<H", resp[:2])[0]] if len(resp) >= 2 else b""
        if len(resp) < 2:
            raise simserver.CardError("empty APDU response")
        return list(resp[:-2]), resp[-2], resp[-1]

    def close(self):
        if self.channel is None:
            return
        ch, self.channel = self.channel, None
        try:
            self.qmi.request(QMI_UIM, UIM_LOGICAL_CHANNEL,
                             tlv(0x01, bytes([SLOT])) + tlv(0x11, bytes([ch]))
                             + tlv(0x13, b"\x01"))
        except Error as e:
            log(f"closing logical channel {ch}: {e}")

    disconnect = close


class MbimUsim(simserver.Usim):
    """server.py's USIM operations (EF reads, AKA, APDUs) over QMI UIM.
    Applications are selected by opening a channel to them, so the EF.DIR
    walk on the basic channel (which the modem uses) is never needed: the
    modem resolves the partial AID."""

    def __init__(self, qmi: Qmi):
        super().__init__(0)
        self.qmi = qmi

    def _connect(self):
        return UimChannel(self.qmi)

    def _select_app(self, conn, aid_prefix: bytes, name: str):
        try:
            conn.open(aid_prefix)
        except simserver.CardError as e:
            raise simserver.CardError(f"no {name}: {e}")


class Handler(simserver.Handler):
    """server.py's API plus serial_server.py's imei and msisdn."""

    imei: str | None = None
    msisdn: str | None = None

    def do_GET(self):
        q = simserver.parse_qs(simserver.urlparse(self.path).query)
        kind = q.get("type", [""])[0]
        if kind == "imei" and self.imei:
            self._reply(200, {"imei": self.imei})
        elif kind == "msisdn" and self.msisdn:
            self._reply(200, {"msisdn": self.msisdn})
        elif kind in ("imei", "msisdn"):
            self._reply(404, {"error": f"the modem reports no {kind}"})
        else:
            super().do_GET()


def start_sim_server(qmi: Qmi, listen: str, m) -> object:
    Handler.usim = MbimUsim(qmi)
    imsi = Handler.usim.imsi()
    Handler.imei = m.device_information.mobile_equipment_id or None
    numbers = list(m.device_information.telephone_numbers or [])
    Handler.msisdn = next((n for n in numbers if n), None)
    host, _, port = listen.rpartition(":")
    srv = simserver.ThreadingTCPHTTPServer((host, int(port)), Handler)
    where = f"http://{listen}"
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    log(f"SIM server on {where}: IMSI {imsi}, IMEI {Handler.imei}, "
        f"MSISDN {Handler.msisdn}")
    return srv, imsi


# -- Windows networking -------------------------------------------------------

def ps(script: str) -> str:
    r = subprocess.run(["powershell", "-NoProfile", "-NonInteractive",
                        "-Command", "$ErrorActionPreference = 'Stop'; "
                        + script], capture_output=True, text=True)
    if r.returncode:
        raise Error(f"PowerShell: {(r.stderr or r.stdout).strip()}")
    return r.stdout


def adapter_state(guid: str) -> dict | None:
    """The IMS adapter: ifIndex, status, IPv6 addresses, gateways."""
    out = ps(f"""
$a = Get-NetAdapter -IncludeHidden | Where-Object InterfaceGuid -eq '{{{guid}}}'
if (-not $a) {{ 'null'; return }}
$addrs = @(Get-NetIPAddress -InterfaceIndex $a.ifIndex -AddressFamily IPv6 -ErrorAction SilentlyContinue |
    ForEach-Object {{ @{{ ip = $_.IPAddress; prefix = $_.PrefixLength; origin = "$($_.PrefixOrigin)";
                         suffix = "$($_.SuffixOrigin)"; skip = [bool]$_.SkipAsSource;
                         state = "$($_.AddressState)" }} }})
$gws = @(Get-NetRoute -InterfaceIndex $a.ifIndex -DestinationPrefix ::/0 -ErrorAction SilentlyContinue |
    ForEach-Object NextHop)
@{{ index = $a.ifIndex; name = $a.Name; status = "$($a.Status)"; addrs = $addrs; gateways = $gws }} |
    ConvertTo-Json -Depth 4 -Compress
""")
    return json.loads(out or "null")


def global_addrs(st: dict) -> list[dict]:
    return [a for a in st["addrs"]
            if not ipaddress.IPv6Address(a["ip"].split("%")[0]).is_link_local]


def ims_address(st: dict) -> str | None:
    """The address the network assigned (MBIM IP configuration, "Manual"
    to Windows), else the stable SLAAC one; never a temporary one."""
    addrs = [a for a in global_addrs(st) if a["state"] == "Preferred"]
    for good in (lambda a: a["origin"] == "Manual",
                 lambda a: a["suffix"] != "Random"):
        for a in addrs:
            if good(a):
                return a["ip"]
    return None


def link_local(st: dict) -> str | None:
    return next((a["ip"].split("%")[0] for a in st["addrs"]
                 if ipaddress.IPv6Address(a["ip"].split("%")[0]).is_link_local),
                None)


# -- DHCPv6 -------------------------------------------------------------------

def dhcp_pcscfs(ifindex: int, source: str, server: str) -> list[str]:
    """P-CSCF addresses from a DHCPv6 Information-Request (dhcp-pcscf.py's
    messages). Unicast to the gateway: a reply to the multicast request
    comes from an address the firewall has seen nothing sent to."""
    duid = struct.pack("!H", 4) + uuid.uuid4().bytes   # DUID-UUID
    xid = os.urandom(3)
    s = socket.socket(socket.AF_INET6, socket.SOCK_DGRAM)
    try:
        s.bind((source, dhcp.CLIENT_PORT, 0, ifindex))
        dest = (server, dhcp.SERVER_PORT, 0,
                ifindex if ipaddress.IPv6Address(server).is_link_local else 0)
        start = time.monotonic()
        rt = 1.0
        while time.monotonic() - start < DHCP_TIMEOUT:
            s.sendto(dhcp.information_request(
                xid, duid, int((time.monotonic() - start) * 100)), dest)
            deadline = min(time.monotonic() + rt, start + DHCP_TIMEOUT)
            while (left := deadline - time.monotonic()) > 0 and \
                    select.select([s], [], [], left)[0]:
                data, peer = s.recvfrom(65535)
                if len(data) < 4 or data[0] != dhcp.REPLY or data[1:4] != xid:
                    continue
                found = []
                for code, value in dhcp.options(data[4:]):
                    if code == dhcp.OPT_SIP_SERVER_A:
                        found += dhcp.v6_list(value)
                    elif code == dhcp.OPT_SIP_SERVER_D:
                        log(f"DHCPv6: P-CSCF names (unused): "
                            f"{' '.join(dhcp.domain_names(value))}")
                log(f"DHCPv6 Reply from {peer[0]}: "
                    f"P-CSCF {' '.join(found) or 'none'}")
                return found
            rt *= 2
    finally:
        s.close()
    raise Error(f"DHCPv6: no Reply from {server} within {DHCP_TIMEOUT}s")


def write_lines(path: str, lines: list[str] | None):
    if not lines:
        if os.path.exists(path):
            os.unlink(path)
        return
    os.makedirs(RUN_DIR, exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w") as f:
        f.write("".join(p + "\n" for p in lines))
    os.replace(tmp, path)


def write_pcscf(pcscfs: list[str] | None, address: str | None = None):
    """The P-CSCF file, and next to it the IMS address for nekoims -l:
    Windows routes the P-CSCF from Wi-Fi's address when the source is left
    open, so nekoims must be told which one to use. The address goes first,
    the pcscf file is what start.ps1 waits for."""
    if pcscfs:
        write_lines(ADDRESS_PATH, [address])
        write_lines(PCSCF_PATH, pcscfs)
    else:
        write_lines(PCSCF_PATH, None)
        write_lines(ADDRESS_PATH, None)


# -- the IMS bearer -----------------------------------------------------------

class Bearer:
    def __init__(self, rt: WinRT, apn: str, metric: int):
        self.rt, self.apn, self.metric = rt, apn, metric
        self.session = None
        self.guid = None
        self.index = None
        self.address = None
        self.pcscfs: list[str] = []

    def up(self):
        ctx = CellularApnContext()
        ctx.access_point_name = self.apn
        ctx.profile_name = "NekoIMS " + self.apn
        log(f"connecting the {self.apn} PDN")
        self.session = self.rt.run(
            lambda: ConnectivityManager.acquire_connection_async(ctx),
            DIAL_TIMEOUT, f"connecting {self.apn}")
        self.guid = str(self.session.connection_profile.network_adapter
                        .network_adapter_id)

        deadline = time.monotonic() + UP_TIMEOUT
        while True:
            st = adapter_state(self.guid)
            if st and st["status"] == "Up" and ims_address(st) and \
                    link_local(st) and st["gateways"]:
                break
            if time.monotonic() > deadline:
                raise Error(f"the {self.apn} adapter got no IPv6 address and "
                            f"gateway within {UP_TIMEOUT}s: {st}")
            time.sleep(1)
        self.index = st["index"]
        self.address = ims_address(st)

        gws = sorted(st["gateways"],
                     key=lambda g: not ipaddress.IPv6Address(g).is_link_local)
        pcscfs = []
        for gw in gws:
            try:
                pcscfs = dhcp_pcscfs(self.index, link_local(st), gw)
                break
            except (Error, OSError) as e:
                log(str(e))
        self.pcscfs = pcscfs
        self.configure(st, gws[0])
        print(f"ims:    {st['name']} (ifIndex {self.index}) {self.address}",
              flush=True)
        print(f"p-cscf: {' '.join(pcscfs) or 'none found'}", flush=True)
        if not pcscfs:
            raise Error("no P-CSCF from DHCPv6")

    def configure(self, st: dict, gateway: str):
        """Metric, P-CSCF routes and source address flags; ActiveStore only,
        they go away with the adapter."""
        script = [f"Set-NetIPInterface -InterfaceIndex {self.index} "
                  f"-AddressFamily IPv6 -InterfaceMetric {self.metric} "
                  "-PolicyStore ActiveStore"]
        for p in self.pcscfs:
            script.append(
                f"Remove-NetRoute -InterfaceIndex {self.index} "
                f"-DestinationPrefix '{p}/128' -Confirm:$false "
                "-ErrorAction SilentlyContinue; "
                f"New-NetRoute -InterfaceIndex {self.index} "
                f"-DestinationPrefix '{p}/128' -NextHop '{gateway}' "
                "-PolicyStore ActiveStore | Out-Null")
        ps("; ".join(script))
        self.fix_sources(st)

    def fix_sources(self, st: dict):
        """SkipAsSource on every global address but ours. Windows keeps
        making temporary addresses, so this is redone on every check."""
        cmds = [f"Set-NetIPAddress -InterfaceIndex {self.index} "
                f"-IPAddress '{a['ip']}' -SkipAsSource "
                f"${str(a['ip'] != self.address).lower()} "
                "-PolicyStore ActiveStore"
                for a in global_addrs(st)
                if a["skip"] != (a["ip"] != self.address)]
        if cmds:
            ps("; ".join(cmds))

    def check(self):
        st = adapter_state(self.guid)
        if not st or st["status"] != "Up":
            raise Error(f"the {self.apn} PDN went down")
        addr = ims_address(st)
        if addr != self.address:
            raise Error(f"the IMS address changed ({self.address} -> {addr})")
        self.fix_sources(st)

    def down(self):
        if self.session is not None:
            try:
                self.rt.call(self.session.close)
            except OSError:
                pass
            self.session = None
        self.guid = self.index = self.address = None


def default_apn(imsi: str) -> str:
    bundle, name = find_bundle(imsi, BUNDLES_DEFAULT)
    log(f"IMSI {imsi}: carrier bundle {name or 'none'}")
    return (bundle or {}).get("apn", "ims")


def is_admin() -> bool:
    import ctypes
    return bool(ctypes.windll.shell32.IsUserAnAdmin())


def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n\n")[0])
    ap.add_argument("--apn", help="IMS APN (default: the carrier bundle's "
                                  "\"apn\", else ims)")
    ap.add_argument("--metric", type=int, default=9000,
                    help="IPv6 interface metric of the IMS adapter, so its "
                         "default route doesn't take over (default "
                         "%(default)s)")
    ap.add_argument("--listen", default=simserver.DEFAULT_TCP,
                    help="SIM server address (default %(default)s)")
    ap.add_argument("--no-sim-server", action="store_true",
                    help="don't serve the modem's SIM")
    ap.add_argument("--log", metavar="PATH",
                    help="append our output here")
    ap.add_argument("--lifeline", action="store_true",
                    help="hang up and exit when stdin closes (for a parent "
                         "process that can't signal us, e.g. start.ps1)")
    args = ap.parse_args()

    if args.log:
        sys.stdout = sys.stderr = open(args.log, "a", buffering=1)
    if args.lifeline:
        import _thread

        def lifeline():
            while os.read(sys.stdin.fileno(), 4096):
                pass
            log("stdin closed, hanging up")
            _thread.interrupt_main()
        threading.Thread(target=lifeline, daemon=True).start()
    if sys.platform != "win32":
        sys.exit("mbim_ims is for Windows; on Linux use qmi_netdev.py")
    if not is_admin():
        sys.exit("must run as Administrator (routes and address flags)")

    rt = WinRT()
    qmi = Qmi(rt)
    srv = bearer = None
    write_pcscf(None)
    try:
        if args.no_sim_server:
            imsi = modem().device_information.subscriber_id
        else:
            srv, imsi = start_sim_server(qmi, args.listen, modem())
        apn = args.apn or default_apn(imsi)

        bearer = Bearer(rt, apn, args.metric)
        delay = RETRY_MIN
        while True:
            try:
                bearer.up()
                write_pcscf(bearer.pcscfs, bearer.address)
                delay = RETRY_MIN
                log("up; Ctrl-C to disconnect")
                while True:
                    time.sleep(POLL)
                    bearer.check()
            except (Error, OSError) as e:
                # Typically suspend/resume, or Windows dropping the PDN
                log(f"mbim_ims: {e}; reconnecting in {delay}s")
                write_pcscf(None)
                bearer.down()
                time.sleep(delay)
                delay = min(delay * 2, RETRY_MAX)
    except KeyboardInterrupt:
        pass
    except (Error, OSError, simserver.CardError) as e:
        sys.exit(f"mbim_ims: {e}")
    finally:
        write_pcscf(None)
        if bearer:
            bearer.down()
        if srv:
            srv.shutdown()
        qmi.close()


if __name__ == "__main__":
    main()
